

const { ccclass, property } = cc._decorator;

@ccclass
export default class NewClass extends cc.Component {
    @property(cc.Node)
    vfxSmoke: cc.Node = null;
    @property(cc.Node)
    iconChin: cc.Node = null;
    gamePlay = null;
    isReady = false;
    value = 0
    start() {
        this.gamePlay = cc.Canvas.instance.node.getComponent("GameApp")
        cc.tween(this.iconChin).to(2, { opacity: 255 }).call(() => {
            this.isReady = true
                    this.node.getComponent(cc.Button).enabled = true

        }).start()
    }
    btn_click() {
        if (!this.isReady) return;
        this.gamePlay.clickHotDog(this.value, this.node);
        this.node.getComponent(cc.Button).enabled = false
    }
    appear() {
        this.node.getComponent(cc.Button).enabled = true;
        this.vfxSmoke.active = true
    }

}
